@push('styles')
<style>
    .agency-page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:25px}.agency-page-head h1{margin:5px 0;font-size:32px}.agency-page-head p,.agency-breadcrumb,.muted{margin:0;color:#64748b}.agency-breadcrumb{font-size:12px}.agency-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:22px}.agency-stat,.agency-card,.agency-form-card{background:#fff;border:1px solid #e2e8f0;border-radius:13px;box-shadow:0 1px 3px #0f172a12}.agency-stat{padding:19px}.agency-stat strong{display:block;font-size:29px}.agency-stat span{color:#64748b;font-size:12px}.agency-card{overflow:hidden}.agency-filters{display:grid;grid-template-columns:2fr 1fr 1.5fr auto;gap:10px;padding:18px;border-bottom:1px solid #e2e8f0}.agency-filters input,.agency-filters select,.agency-form-card input,.agency-form-card select{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}.agency-table-wrap{overflow-x:auto}.agency-table{width:100%;border-collapse:collapse}.agency-table th,.agency-table td{padding:14px 18px;text-align:left;border-bottom:1px solid #e2e8f0}.agency-table th{font-size:11px;text-transform:uppercase;color:#64748b;background:#f8fafc}.agency-cell{display:flex;align-items:center;gap:11px;min-width:190px}.agency-icon{width:38px;height:38px;display:grid;place-items:center;border-radius:8px;background:#E8F5F0;color:var(--green);font-weight:800}.agency-cell small{display:block;color:#64748b;margin-top:3px}.agency-status{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border-radius:99px;font-size:12px;font-weight:700}.agency-status:before{content:'';width:6px;height:6px;border-radius:50%;background:currentColor}.agency-status.active{background:#dcfce7;color:#166534}.agency-status.inactive{background:#f1f5f9;color:#475569}.agency-link{color:var(--green);font-weight:700;text-decoration:none}.agency-pagination{padding:18px}.agency-detail-grid{display:grid;grid-template-columns:2fr 1fr;gap:18px}.agency-card-head{padding:17px 20px;border-bottom:1px solid #e2e8f0}.agency-card-head h2{margin:0;font-size:18px}.agency-card-body{padding:20px}.agency-info{display:grid;grid-template-columns:repeat(2,1fr);gap:19px}.agency-info small{display:block;color:#64748b;text-transform:uppercase;font-size:10px;font-weight:700;margin-bottom:5px}.agency-count{padding:16px;border-radius:10px;background:#f8fafc;margin-bottom:10px}.agency-count strong{display:block;font-size:25px}.agency-form-card{overflow:hidden}.agency-form-section{padding:24px}.agency-form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.agency-field.full{grid-column:1/-1}.agency-field label{display:block;margin-bottom:7px;font-size:13px;font-weight:700}.agency-field input:focus,.agency-field select:focus{outline:3px solid #E8F5F0;border-color:var(--green)}.agency-field .invalid{border-color:var(--danger)}.agency-error{display:block;color:#b91c1c;font-size:12px;margin-top:5px}.agency-errors{margin:0 24px 20px;padding:14px;border-radius:9px;background:#fef2f2;color:#991b1b}.agency-form-footer{display:flex;justify-content:flex-end;gap:10px;padding:18px 24px;border-top:1px solid #e2e8f0;background:#f8fafc}.required{color:var(--danger)}
    @media(max-width:900px){.agency-summary{grid-template-columns:repeat(2,1fr)}.agency-filters,.agency-detail-grid{grid-template-columns:1fr}}@media(max-width:650px){.agency-page-head{align-items:flex-start;flex-direction:column}.agency-summary,.agency-form-grid,.agency-info{grid-template-columns:1fr}.agency-field.full{grid-column:auto}.agency-form-footer{flex-direction:column-reverse}.agency-form-footer .btn{width:100%}}
</style>
@endpush
